export type ParsedRetryVrfInstruction<
  TProgram extends string = typeof DEADROLL_SESSION_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /**
     * Any participant: a player's main wallet or session key (with its `participation`), or the
     * DM's (without one). Pays the VRF fee.
     */
    signer: TAccountMetas[0];
    session: TAccountMetas[1];
    monsters: TAccountMetas[2];
    /** The signer's participation in this party; none when the DM signs. */
    participation?: TAccountMetas[3] | undefined;
    /** MagicBlock `SessionTokenV2` of the session key; none when a main wallet signs. */
    sessionToken?: TAccountMetas[4] | undefined;
    programIdentity: TAccountMetas[5];
    oracleQueue: TAccountMetas[6];
    vrfProgram: TAccountMetas[7];
    slotHashes: TAccountMetas[8];
    systemProgram: TAccountMetas[9];
  };
  data: RetryVrfInstructionData;
};

export function parseRetryVrfInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRetryVrfInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === DEADROLL_SESSION_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      signer: getNextAccount(),
      session: getNextAccount(),
      monsters: getNextAccount(),
      participation: getNextOptionalAccount(),
      sessionToken: getNextOptionalAccount(),
      programIdentity: getNextAccount(),
      oracleQueue: getNextAccount(),
      vrfProgram: getNextAccount(),
      slotHashes: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getRetryVrfInstructionDataDecoder().decode(instruction.data),
  };
}
